// ===== Classify Customer Intent V7: Naya Menu + Herbs + Custom Order + Rage Filter + GUARD =====
function distance(a,b) {
  if (Math.abs(a.length-b.length)>2) return 3;
  let prior=Array.from({length:b.length+1},(_,i)=>i);
  for(let i=1;i<=a.length;i++) {
    const next=[i];
    for(let j=1;j<=b.length;j++) next[j]=Math.min(next[j-1]+1,prior[j]+1,prior[j-1]+(a[i-1]===b[j-1]?0:1));
    prior=next;
  }
  return prior[b.length];
}
function aliases(row) {
  const raw=row.aliases || row.search_aliases || '';
  let list=raw;
  if(typeof raw==='string') {
    try { list=JSON.parse(raw); } catch { list=raw.split(','); }
  }
  return [row.name,...(Array.isArray(list)?list:[])].filter(Boolean).map(normalize);
}
function findProduct(query,rows) {
  if(!query || query.length<3) return null;
  const matches=[];
  for(const row of rows) for(const alias of aliases(row)) {
    if(!alias || alias.length<3) continue;
    const exact=query===alias || (` ${query} `).includes(` ${alias} `);
    const words=query.split(' ');
    const fuzzy=alias.length>=5 && words.some(word=>word.length>=4 && Math.abs(word.length-alias.length)<=2 && distance(word,alias)<= (alias.length>=7?2:1));
    if(exact||fuzzy) matches.push({row,score:exact?100+alias.length:alias.length});
  }
  matches.sort((a,b)=>b.score-a.score);
  if(!matches.length || (matches[1] && matches[0].score===matches[1].score && matches[0].row.name!==matches[1].row.name)) return null;
  return matches[0].row;
}
function normalize(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .toLowerCase()
    .replace(/[\u200B-\u200F\uFEFF]/g, '')
    .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
    .replace(/[أإآ]/g, 'ا')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function exact(value, list) {
  return list.some(x => value === normalize(x));
}
function has(value, list) {
  const padded = ` ${value} `;
  return list.some(x =>
    padded.includes(` ${normalize(x)} `)
  );
}
function looksLikeQuestion(text, raw) {
  if (/\?|؟/.test(raw || '')) return true;
  return has(text, [
    'kya','kia','kaise','kese','kesa','kaisa','kyun','kyu','kab','kahan','kitna','kitne','kitni',
    'kaun','kon','konsa','faida','fayda','faide','fayde','benefit','benefits','nutrition',
    'price','rate','cost','detail','details','info','jankari','batao','batado',
    'istemal','istamal','istemaal','tarika','tareeka','use','what','how','when','where','why','which',
    'کیا','کیسے','کب','کہاں',
  ]);
}
function safeContext(source) {
  try {
    const value =
      typeof source === 'string'
        ? JSON.parse(source || '{}')
        : (source || {});
    return value &&
      typeof value === 'object' &&
      !Array.isArray(value)
      ? value
      : {};
  } catch {
    return {};
  }
}
function isQuantityChange(raw) {
  const q = String(raw || '').normalize('NFKC').toLowerCase().replace(/,/g, '.').trim();
  return /^(make it |karo |kar do |change |badal |chahiye )?\d+(?:\.\d+)?\s*(g|gm|gram|grams|kg|kgs|kilogram|kilograms|box|boxes|pack|packs|packet|packets|piece|pieces|pc|pcs)?\s*(chahiye|hai)?$/.test(q);
}
function extractQuantity(raw) {
  const m = String(raw || '').normalize('NFKC').toLowerCase().replace(/,/g, '.').match(/(\d+(?:\.\d+)?)\s*(g|gm|gram|grams|kg|kgs|kilogram|kilograms|box|boxes|pack|packs|packet|packets|piece|pieces|pc|pcs)?\s*$/);
  return m ? (m[1] + (m[2] ? m[2] : '')) : String(raw || '').trim();
}

// ===== RAGE FILTER: abuse vs complaint =====
const ABUSE_WORDS = [
  'fraud','fraudster','chor','loot','lootere','ghatiya','bakwas','bekar','pagal','pagal ho',
  'harami','haraami','bewakoof','ullu','ullu ka patha','third class','3rd class','nalayak',
  'badtameez','jali','scam','scammer','dhoka','cheater','cheat','stupid','idiot','fool',
  'nonsense','rubbish','worst','pathetic','useless','chor hai','loot rahe','loot rahe ho',
];
const COMPLAINT_WORDS = [
  'kharab','damaged','damage','toota','tuti','broken','ghalat','wrong','missing',
  'refund','wapas','return','complain','complaint','shikayat','shikwa','shikvaat',
];

const CHOICES = {
  menu_catalogue: 'browse_products',
  menu_deals: 'deals',
  menu_herbs: 'herbs_spices',
  menu_custom: 'custom_order',
  menu_tracking: 'order_status',
  menu_faq: 'faq_help',
  menu_ai: 'ai_start',
  menu_human: 'human_support',
  // legacy buttons (purane menu wale customers ke liye)
  menu_dry_fruits: 'browse_products',
  menu_snacks: 'browse_products',
  menu_gift_boxes: 'browse_products',
  confirm_yes: 'confirm_order',
  confirm_no: 'cancel_order',
};
const NUMBERS = {
  '1': 'browse_products',
  '2': 'deals',
  '3': 'herbs_spices',
  '4': 'custom_order',
  '5': 'order_status',
  '6': 'faq_help',
  '7': 'ai_start',
  '8': 'human_support',
  '9': 'human_support', // legacy
  '0': 'menu',
};
const MENU_CATEGORIES = {
  menu_dry_fruits: 'Dry Fruits & Nuts',
  menu_snacks: 'Snacks & Seeds',
  menu_gift_boxes: 'Gift Boxes',
};
const TITLE_KEYWORDS = [
  [/catalog/i, 'browse_products', null],
  [/deal|offer/i, 'deals', null],
  [/herbs?\s*&?\s*spices?|herbs|spices|masala/i, 'herbs_spices', null],
  [/custom\s*order|custom|special order/i, 'custom_order', null],
  [/dry fruit/i, 'browse_products', 'Dry Fruits & Nuts'],
  [/snack/i, 'browse_products', 'Snacks & Seeds'],
  [/gift/i, 'browse_products', 'Gift Boxes'],
  [/order/i, 'place_order', null],
  [/track/i, 'order_status', null],
  [/ai health|health bot/i, 'ai_start', null],
  [/faq|help/i, 'faq_help', null],
  [/human|support/i, 'human_support', null],
];
const catalogue = $input.all().map(item => item.json || {}).filter(row => row.active !== false && row.name);
const item = {json: $('Prepare Conversation Context').first().json};
return [(() => {
  const index = 0;
  const data = item.json || {};
  const rawText =
    typeof data.text === 'string'
      ? data.text.trim()
      : String(data.text?.body || '').trim();
  const text = normalize(rawText);
  const rawChoice = String(data.choiceId || '')
    .trim()
    .toLowerCase();
  const command = values =>
    exact(text, values) || exact(rawChoice, values.map(x => normalize(x)));
  let state = String(
    data.sessionState ||
    data.state ||
    'idle'
  ).trim().toLowerCase();
  const expiresAt = Date.parse(data.expires_at || '');
  if (
    data.active === false ||
    data.active === 'false' ||
    (
      Number.isFinite(expiresAt) &&
      expiresAt <= Date.now()
