  ) {
    state = 'idle';
  }
  const context = safeContext(
    data.sessionContext ?? data.context_json
  );
  let intent = 'unknown';
  let confidence = 0;
  const duplicate = Boolean(data.last_message_id && data.last_message_id === data.messageId);
  const isText = ['text','button','interactive','reaction'].includes(String(data.messageType || '').toLowerCase());

  // ===== GUARD (NAYA): opt-out text pehchano — forceMenu inhe khae ga nahi =====
  const isOptOutText = command([
    'cancel', 'cancel order', 'cancel_order', 'order cancel', 'cancel karo', 'cancel kardo', 'cancel krdo', 'کینسل', 'منسوخ',
    'stop', 'stop messages', 'stop reminders', 'reminder band', 'reminders band',
    'band karo', 'band kardo', 'band krdo', 'nahi chahiye', 'nahin chahiye', 'abhi nahi chahiye',
  ]);
  // ===== FIX: PEHLA MSG = HAMESHA MENU (opt-out text chhod kar) =====
  const trackingIds = [...new Set([
    ...[...rawText.matchAll(/\bab[\s:-]*(\d{8})[\s:-]*(\d{4,6})[\s:-]*(\d{2,4})(?![a-z0-9-])/gi)]
      .map(m => 'AB-' + m[1] + '-' + m[2] + '-' + m[3]),
    ...[...rawText.matchAll(/\bab[\s:-]*(\d{8})[\s:-]*([a-f0-9]{6})(?![a-z0-9-])/gi)]
      .map(m => 'AB-' + m[1] + '-' + m[2].toUpperCase()),
  ])];
  const isTrackingRequest = trackingIds.length > 0 || command([
    'tracking', 'track', 'order status', 'track order', 'track my order',
    'where is my order', 'order kahan hai', 'mera order kahan hai',
  ]) || has(text, ['track my order', 'track order', 'where is my order', 'order kahan hai']);
  const forceMenu = (state === 'idle' && !rawChoice && !isOptOutText && !isTrackingRequest);

  if (duplicate) {
    intent = 'duplicate_message'; confidence = 1;
  } else if (forceMenu) {
    intent = 'menu'; confidence = 1;
  } else if (!isText || (!rawText && !rawChoice)) {
    intent = 'unsupported_media'; confidence = 1;
  } else if (
    command([
      'cancel',
      'cancel order',
      'cancel_order',
      'order cancel',
      'cancel karo',
      'cancel kardo',
      'cancel krdo',
      'کینسل',
      'منسوخ',
    ])
  ) {
    intent = 'cancel_order';
    confidence = 1;
  } else if (
    // ===== GUARD (NAYA): STOP / soft opt-out → cancel_order =====
