    data.trackingOrderId = 'AB-' + websiteId[1] + '-' + websiteId[2].toUpperCase();
  } else if (
    /^ab[\s:-]*\d{4,8}[\s:-]*\d{4,6}[\s:-]*\d{2,4}$/i.test(rawText.trim())
  ) {
    // ===== ORDER ID: spaces/dashes dono canonical =====
    intent = 'order_status';
    confidence = 1;
    const oidParts = rawText.trim().match(/^ab[\s:-]*(\d{4,8})[\s:-]*(\d{4,6})[\s:-]*(\d{2,4})$/i);
    data.trackingOrderId = 'AB-' + oidParts[1] + '-' + oidParts[2] + '-' + oidParts[3];
  } else if (rawChoice.startsWith('cat_')) {
    const catMap = { cat_dryfruits:'Dry Fruits & Nuts', cat_oils:'Oils', cat_desi:'Desi Essentials',
      cat_snacks:'Snacks & Seeds', cat_gifts:'Gift Boxes', cat_herbs:'Herbs & Spices' };
    intent = 'browse_products'; confidence = 1;
    data.browseCategory = catMap[rawChoice] || '';
  } else if (rawChoice.startsWith('prod_')) {
    const prow = catalogue.find(r => String(r.base_product_id).toLowerCase() === rawChoice.slice(5));
    if (prow) {
      intent = 'order_product'; confidence = 1;
      data.selectedProductId = String(prow.base_product_id);
      data.selectedProduct = prow.name;
    } else {
      intent = 'browse_products'; confidence = 0.9;
    }
  } else if (rawChoice.startsWith('qty_')) {
    const bodyStr = rawChoice.slice(4);
    const cut = bodyStr.lastIndexOf('_');
    const pid = bodyStr.slice(0, cut);
    const tail = bodyStr.slice(cut + 1);
    const prow = catalogue.find(r => String(r.base_product_id).toLowerCase() === pid);
    if (prow) {
      data.selectedProductId = String(prow.base_product_id);
      data.selectedProduct = prow.name;
      if (tail === 'custom') {
        intent = 'order_quantity_custom'; confidence = 1;
        data.customQty = true;
      } else {
        intent = 'order_quantity'; confidence = 1;
        data.quantityChoice = tail;
      }
    } else {
      intent = 'menu'; confidence = 1;
    }
  } else if (rawChoice.startsWith('win_')) {
    // ===== DELIVERY WINDOW BUTTON: win_fastest::AB-... =====
    const parts = rawChoice.slice(4).split('::');
    const wtype = (parts[0] || '').trim();
    const joid = (parts[1] || '').trim();
    const wmap = { fastest: 'Fastest', morning: 'Morning', evening: 'Evening', night: 'Night' };
    if (wmap[wtype] && joid) {
      intent = 'delivery_window'; confidence = 1;
      data.windowChoice = wmap[wtype];
      data.journeyOrderId = joid;
    } else {
      intent = 'menu'; confidence = 1;
    }
  } else if (rawChoice.startsWith('fb_')) {
    // ===== FEEDBACK BUTTON: fb_great::AB-... =====
    const parts = rawChoice.slice(3).split('::');
    const ftype = (parts[0] || '').trim();
    const joid = (parts[1] || '').trim();
    const fmap = { great: 'great', good: 'good', ok: 'ok', bad: 'bad' };
    if (fmap[ftype] && joid) {
      intent = 'feedback'; confidence = 1;
      data.feedbackRating = ftype;
      data.journeyOrderId = joid;
    } else {
      intent = 'menu'; confidence = 1;
    }
  } else if (CHOICES[rawChoice]) {
    intent = CHOICES[rawChoice];
    confidence = 1;
    if (MENU_CATEGORIES[rawChoice]) {
      data.browseCategory = MENU_CATEGORIES[rawChoice];
    }
  } else if (rawChoice) {
    const numMatch = rawChoice.match(/^(\d+)\s*[\.\)]?\s*/);
    const numKey = numMatch ? numMatch[1] : '';
    if (numKey && NUMBERS[numKey]) {
      intent = NUMBERS[numKey];
      confidence = 1;
      if (MENU_CATEGORIES[numKey]) {
        data.browseCategory = MENU_CATEGORIES[numKey];
      }
    } else {
      const kw = TITLE_KEYWORDS.find(([re]) => re.test(rawChoice));
      if (kw) {
        intent = kw[1];
        confidence = 1;
        if (kw[2]) data.browseCategory = kw[2];
      } else {
        intent = 'menu'; confidence = 0.8;
      }
    }
  } else if (
    command([
      'menu',
      'main menu',
      'home',
      'start',
      'hi',
      'hello',
      'hey',
      'salam',
      'assalamualaikum',
      'اسلام علیکم',
      'السلام عليكم',
    ])
  ) {
    intent = 'menu';
    confidence = 1;
  } else if (
    command([
      'human',
      'human support',
      'support',
      'agent',
      'representative',
      'customer support',
      'talk to human',
      'human se baat',
    ])
  ) {
    intent = 'human_support';
    confidence = 1;
  } else if (
    command([
      'tracking',
      'track',
      'order status',
      'track order',
      'track my order',
      'where is my order',
      'order kahan hai',
    ])
  ) {
    intent = 'order_status';
    confidence = 1;
  } else if (
    command([
      'order',
      'new order',
      'place order',
      'place_order',
      'buy',
      'order karna hai',
    ])
  ) {
    intent = 'place_order';
    confidence = 1;
  } else if (
    command(['ai', 'ai bot', 'health bot', 'ai health bot', 'health', 'sehat'])
  ) {
    intent = 'ai_start';
    confidence = 1;
  } else if (
    // ===== RAGE FILTER: abuse → direct human (quiet mode mein nahi) =====
    has(text, ABUSE_WORDS) && state !== 'human_handoff'
  ) {
    intent = 'human_support'; confidence = 1;
    data.rageFlag = true;
  } else if (
    // ===== COMPLAINT: AI details collect karega =====
    has(text, COMPLAINT_WORDS) && state !== 'human_handoff' && state !== 'awaiting_custom_order'
  ) {
    intent = 'faq'; confidence = 1;
    data.complaintFlag = true;
  } else if (state === 'ai_chat') {
    intent = 'faq';
    confidence = 0.95;
  } else if (state === 'human_handoff') {
    // ===== BOT QUIET MODE: free-text SILENT drop =====
    intent = 'duplicate_message';
    confidence = 1;
  } else if (state === 'awaiting_custom_order') {
    // ===== CUSTOM ORDER: customer apni desired product likh raha hai =====
    if (rawText.length >= 3) {
      intent = 'custom_order_details'; confidence = 1;
    } else {
      intent = 'custom_order_details'; confidence = 0.7;
    }
  } else if (
    has(text, [
      'products',
      'product',
      'catalogue',
      'catalog',
      'items',
      'saman',
      'saaman',
      'price list',
      'kya bikta',
      'kya milta',
    ]) &&
    !has(text, ['order','buy','purchase','khareedna','kharidna'])
  ) {
    intent = 'browse_products';
    confidence = 0.9;
  } else if (
    looksLikeQuestion(text, rawText) &&
    !has(text, ['order','buy','purchase','khareedna','kharidna'])
  ) {
    intent = 'faq';
    confidence = 0.9;
  } else if (has(text,['order','buy','purchase','khareedna','kharidna']) && findProduct(text,catalogue)) {
    intent = 'order_product'; confidence = 0.94;
  } else if (state === 'awaiting_confirmation') {
    if (
      command([
        'yes',
        'confirm',
        'ok',
        'okay',
        'haan',
        'han',
        'ji',
        'jee',
        '1',
      ])
    ) {
      intent = 'confirm_order';
      confidence = 1;
    } else if (
      command([
        'no',
        'nahi',
        'nahin',
        '2',
      ])
    ) {
      intent = 'cancel_order';
      confidence = 1;
    } else if (isQuantityChange(rawText) && (context.product || data.selectedProduct)) {
      // ===== MID-ORDER QUANTITY CHANGE =====
