    if (rawText.length <= 80 && findProduct(text, catalogue)) {
      intent = 'order_product';
      confidence = 0.95;
    } else if (looksLikeQuestion(text, rawText)) {
      intent = 'faq';
      confidence = 0.9;
    } else {
      intent = 'order_product_invalid';
      confidence = 1;
    }
  } else if (state === 'awaiting_quantity') {
    const quantityText = rawText
      .normalize('NFKC')
      .toLowerCase()
      .replace(/,/g, '.')
      .replace(/\s+/g, ' ')
      .trim();
    const quantityMatch = quantityText.match(
      /^(\d+(?:\.\d+)?)\s*(g|gm|gram|grams|kg|kgs|kilogram|kilograms|box|boxes|pack|packs|packet|packets|piece|pieces|pc|pcs)?$/
    );
    const amount = quantityMatch
      ? Number(quantityMatch[1])
      : NaN;
    if (
      quantityMatch &&
      Number.isFinite(amount) &&
      amount > 0 &&
      amount <= 10000
    ) {
      intent = 'order_quantity';
      confidence = 1;
    } else if (looksLikeQuestion(text, rawText)) {
      intent = 'faq';
      confidence = 0.9;
    } else {
      intent = 'order_quantity_invalid';
      confidence = 1;
    }
  } else if (state === 'awaiting_address') {
    if (isQuantityChange(rawText) && (context.product || data.selectedProduct)) {
      intent = 'order_quantity';
      confidence = 1;
      data.quantityChoice = extractQuantity(rawText);
    } else if (
      rawText.length >= 12 &&
      rawText.length <= 300 &&
      rawText.includes(' ')
    ) {
      intent = 'order_address';
      confidence = 0.95;
    } else {
      intent = 'order_address_invalid';
      confidence = 1;
    }
  } else if (state === 'awaiting_delivery_window') {
    // ===== DELIVERY WINDOW: text reply (button ya text dono) =====
    let wc = '';
    if (has(text, ['fastest', 'jaldi', 'turant', 'foran', 'fast'])) wc = 'Fastest';
    else if (has(text, ['morning', 'subah', 'saveray', 'savere'])) wc = 'Morning';
    else if (has(text, ['evening', 'sham', 'shaam'])) wc = 'Evening';
    else if (has(text, ['night', 'raat', 'rat'])) wc = 'Night';
    if (wc) {
      intent = 'delivery_window'; confidence = 1;
      data.windowChoice = wc;
      data.journeyOrderId = context.order_id || data.journeyOrderId || '';
    } else if (looksLikeQuestion(text, rawText)) {
      intent = 'faq'; confidence = 0.9;
    } else {
      intent = 'delivery_window_invalid'; confidence = 1;
    }
  } else if (state === 'awaiting_landmark') {
    // ===== LANDMARK: text reply =====
    if (/^\d{1,3}$/.test(rawText.trim())) {
      intent = 'menu'; confidence = 1;
    } else if (rawText.length >= 3 && rawText.length <= 120) {
      intent = 'landmark'; confidence = 1;
    } else if (looksLikeQuestion(text, rawText)) {
      intent = 'faq'; confidence = 0.9;
    } else {
      intent = 'landmark'; confidence = 0.7;
    }
  } else if (NUMBERS[text]) {
    intent = NUMBERS[text];
    confidence = 1;
    if (MENU_CATEGORIES[text]) {
      data.browseCategory = MENU_CATEGORIES[text];
